(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[130],{1469:function(t,e,n){"use strict";n.r(e),e.default={code:"114TCPE09",title:"114-澎湖縣國小（競賽模式）",unlockCode:"114TCPE09",tasks:[{id:"114TCPE09-1",code:"114TCPE09-114TCPE09-1",title:"神秘的運算符號",description:"小明自己發明了一個特別的運算符號「#」。當你看到 A # B 的時候，代表要用 A 和 B 這兩個數字來進行一個新的計算。\n計算時，先找出這兩個數字中較大的數和較小的數（不管輸入順序）。\n接著，用「較大的數」除以「較小的數」，算出商與餘數。\n最後，把「商」放在前面、「餘數」放在後面，直接接在一起，變成一個新的數字，這就是「#」運算的答案。如果剛好整除，餘數是 0，也要照樣寫出來，不能省略。",examples:[{input:"5\n10",output:"20",explanation:"較大的數是10，較小的數是5。10÷5＝2餘0，商2接餘數0，得到20。"},{input:"10\n5",output:"20",explanation:"不管輸入順序，較大的數還是10，較小的數還是5，結果一樣是20。"},{input:"3\n4",output:"11",explanation:"較大的數是4，較小的數是3。4÷3＝1餘1，商1接餘數1，得到11。"}],testCases:[{input:"5\n10",expectedOutput:"20",score:10},{input:"3\n3",expectedOutput:"10",score:10},{input:"8\n100",expectedOutput:"124",score:10},{input:"45\n7",expectedOutput:"63",score:10},{input:"1\n13",expectedOutput:"130",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE09-2",code:"114TCPE09-114TCPE09-2",title:"甜心餅乾工廠的品管任務",description:"品管機器人「阿波」站在包裝輸送帶前面，確保每一塊「甜心餅乾」都是正面朝上。\n1 代表正面（不用翻），0 代表反面（需要翻面）。每翻一塊餅乾，計數器就會 +1。\n請計算阿波總共翻了幾次餅乾。",examples:[{input:"8\n1 0 1 1 0 0 1 1",output:"3",explanation:"8 塊餅乾中有 3 塊是反面（0），所以翻了 3 次。"}],testCases:[{input:"8\n1 0 1 1 0 0 1 1",expectedOutput:"3",score:10},{input:"5\n1 1 1 1 1",expectedOutput:"0",score:10},{input:"7\n0 0 0 0 0 0 0",expectedOutput:"7",score:10},{input:"1\n1",expectedOutput:"0",score:10},{input:"1\n0",expectedOutput:"1",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE09-3",code:"114TCPE09-114TCPE09-3",title:"麵包店打折趣",description:"小明到幸福麵包店買麵包，每個麵包的價格都一樣。店員說：「如果總金額滿 100 元可以打 9 折，滿 200 元打 85 折，滿 300 元打 8 折喔！」\n請算出小明這次要付多少錢（四捨五入到整數）。",examples:[{input:"5\n25",output:"113",explanation:"總金額 5×25=125 元，滿 100 打 9 折，125×0.9=112.5，四捨五入為 113。"}],testCases:[{input:"5\n25",expectedOutput:"113",score:10},{input:"3\n30",expectedOutput:"90",score:10},{input:"4\n25",expectedOutput:"90",score:10},{input:"6\n27",expectedOutput:"146",score:10},{input:"5\n40",expectedOutput:"170",score:10},{input:"9\n25",expectedOutput:"191",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE09-4",code:"114TCPE09-114TCPE09-4",title:"魔法學院的神秘藥水調配挑戰",description:"你桌上有三瓶貼著不同數字標籤的神奇藥材，要調配傳說藥水，必須遵照「三步驟黃金法則」：\n第一步：把三瓶藥材按數字排出「最小瓶」、「中間瓶」、「最大瓶」。\n第二步：把三個數字加起來得到「總和」，若總和是偶數啟動「太陽魔法陣」，若是奇數啟動「月亮魔法陣」。\n第三步：依魔法陣念出咒語：\n太陽魔法陣：(最小瓶數字 + 中間瓶數字) × 最大瓶數字\n月亮魔法陣：(最大瓶數字 - 中間瓶數字) + 最小瓶數字\n請輸出最終的「魔力指數」。",examples:[{input:"2\n3\n5",output:"25",explanation:"排序後最小2、中間3、最大5，總和10是偶數，啟動太陽魔法陣：(2+3)×5=25。"},{input:"10\n1\n4",output:"7",explanation:"排序後最小1、中間4、最大10，總和15是奇數，啟動月亮魔法陣：(10-4)+1=7。"}],testCases:[{input:"2\n3\n5",expectedOutput:"25",score:10},{input:"10\n1\n4",expectedOutput:"7",score:10},{input:"1\n2\n3",expectedOutput:"9",score:10},{input:"2\n3\n4",expectedOutput:"3",score:10},{input:"10\n5\n3",expectedOutput:"80",score:10},{input:"9\n4\n6",expectedOutput:"7",score:10},{input:"7\n1\n7",expectedOutput:"1",score:10}],difficulty:"L3",sb3Path:null}]}}}]);